const ELEMENT_PROP_KEYS = new Set(["title","width","height","fontSize","glassColor","staggerFrames","showTrafficLights","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  title: "hero.tsx",
  width: 760,
  height: 460,
  fontSize: 16,
  glassColor: "rgba(10, 10, 10, 0.6)",
  staggerFrames: 4,
  showTrafficLights: true,
  speed: 1,
};

type GlassCodeBlockElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof GlassCodeBlockBase>;

const GlassCodeBlockInner = forwardRef<
  HTMLDivElement,
  GlassCodeBlockElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<GlassCodeBlock>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <GlassCodeBlockBase
          {...(componentProps as unknown as ComponentProps<typeof GlassCodeBlockBase>)}
        />
      </div>
    </Sequence>
  );
});

export const GlassCodeBlock = Interactive.withSchema({
  Component: GlassCodeBlockInner,
  componentName: "<GlassCodeBlock>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
